fragment:
precision highp float;
varying vec2 vUV;
uniform sampler2D uImage;
uniform float uPhase;
const vec2 px=vec2(1.0/1920.0,1.0/1080.0);
float luminance(vec3 c){return dot(c,vec3(0.2126,0.7152,0.0722));}
void main(){
  float p=uPhase;
  vec2 uv=(vUV-0.5)/1.10+0.5;

  // A small closed camera orbit supports the more visible cloud drift.
  uv+=vec2(8.0*sin(p),5.0*cos(p))*px;

  vec3 guide=texture2D(uImage,uv).rgb;
  float center=luminance(guide);
  float around=(
    luminance(texture2D(uImage,uv+vec2(7.0,0.0)*px).rgb)+
    luminance(texture2D(uImage,uv-vec2(7.0,0.0)*px).rgb)+
    luminance(texture2D(uImage,uv+vec2(0.0,7.0)*px).rgb)+
    luminance(texture2D(uImage,uv-vec2(0.0,7.0)*px).rgb)
  )*0.25;
  float detail=abs(center-around);
  float textureMask=smoothstep(0.0012,0.020,detail);
  float pinkMask=smoothstep(0.018,0.13,guide.r-guide.g);
  float whiteMask=smoothstep(0.76,0.96,center)*0.72;
  float cloud=max(textureMask,max(pinkMask,whiteMask));

  // Broad flow carries the long ribbons; the finer wave gives the wisps a
  // restrained curl. Both fields travel and return exactly after one cycle.
  vec2 broad=vec2(
    54.0*sin(uv.y*7.5-p)+17.0*sin(uv.x*5.0-2.0*p),
    22.0*cos(uv.x*6.0-p)+10.0*sin(uv.y*8.0-2.0*p)
  );
  vec2 wisps=vec2(
    17.0*sin(uv.y*16.0-2.0*p),
    9.0*cos(uv.x*13.0-p)
  );
  uv+=(broad*(0.28+0.72*cloud)+wisps*cloud)*px;

  // The broad ribbons also bend around the bright opening in the sky. This
  // curl is deliberately pronounced, while remaining a closed periodic move.
  vec2 curlCenter=vec2(0.57,0.14);
  vec2 local=uv-curlCenter;
  local.x*=1.7777778;
  float radius=length(local);
  float curlFalloff=smoothstep(0.88,0.10,radius)*cloud;
  float angle=(0.030*sin(p)+0.012*sin(2.0*p+radius*11.0))*curlFalloff;
  float s=sin(angle),c=cos(angle);
  local=mat2(c,-s,s,c)*local;
  local.x/=1.7777778;
  uv=curlCenter+local;

  gl_FragColor=vec4(texture2D(uImage,uv).rgb,1.0);
}
